const contract = { id: "C-17", history: [] };                 // continuity
const snapshot = (terms) => Object.freeze({ ...terms });      // version value
const current = () => contract.history.at(-1).terms;
function amend(effective, changes) {
  contract.history.push({ effective: +new Date(effective),
                          terms: snapshot({ ...current(), ...changes }) });
  contract.history.sort((a, b) => a.effective - b.effective);  // keep ascending
}
const asOf = (date) => contract.history.findLast(v => v.effective <= +new Date(date))?.terms ?? null;
